function cleanAgentOutput(value) {
  if (value == null) return '';
  if (typeof value !== 'string') return JSON.stringify(value);
  return value
    .replace(/^\s*\`\`\`(?:json)?\s*/i, '')
    .replace(/\`\`\`\s*$/i, '')
    .trim();
}

function parseJsonFromOutput(value) {
  const cleaned = cleanAgentOutput(value);
  try {
    return JSON.parse(cleaned);
  } catch (firstError) {
    const startObject = cleaned.indexOf('{');
    const startArray = cleaned.indexOf('[');
    const starts = [startObject, startArray].filter(i => i >= 0);
    if (!starts.length) throw firstError;

    const start = Math.min(...starts);
    const end = cleaned.lastIndexOf(cleaned[start] === '[' ? ']' : '}');
    if (end <= start) throw firstError;
    return JSON.parse(cleaned.slice(start, end + 1));
  }
}

let parsed;
try {
  parsed = parseJsonFromOutput($json.output);
} catch (e) {
  throw new Error('Could not parse Literature Agent output as JSON: ' + e.message + '\nRaw output: ' + String($json.output || '').slice(0, 1000));
}

const form = $('Research Form').first().json;
const topic = form['Research topic'] || form.topic || '';
const requested = parseInt(form['Max papers'] || form.max_papers || 5, 10);
const maxPapers = Number.isFinite(requested) && requested > 0 ? requested : 5;
const papers = Array.isArray(parsed) ? parsed : (parsed.papers || parsed.results || []);

if (!papers.length) {
  throw new Error('Literature Agent returned no papers. Check the tool calls and the agent output JSON shape.');
}

return papers.slice(0, maxPapers).map(function (paper) {
  return {
    json: {
      topic,
      title: paper.title || '',
      authors: Array.isArray(paper.authors) ? paper.authors : (paper.authors ? String(paper.authors).split(/,\s*/) : []),
      year: paper.year || null,
      abstract: paper.abstract || paper.summary || paper.relevance_reason || '',
      source: paper.source || '',
      url: paper.url || paper.link || '',
      doi: paper.doi || null,
      citations: paper.citations ?? paper.citation_count ?? null,
      relevance_reason: paper.relevance_reason || '',
      paper_type: paper.paper_type || ''
    }
  };
});

function cleanAgentOutput(value) {
  if (value == null) return '';
  if (typeof value !== 'string') return JSON.stringify(value);
  return value
    .replace(/^\s*\`\`\`(?:json)?\s*/i, '')
    .replace(/\`\`\`\s*$/i, '')
    .trim();
}

function parseJsonFromOutput(value) {
  const cleaned = cleanAgentOutput(value);
  try {
    return JSON.parse(cleaned);
  } catch (firstError) {
    const startObject = cleaned.indexOf('{');
    const startArray = cleaned.indexOf('[');
    const starts = [startObject, startArray].filter(function (i) { return i >= 0; });
    if (!starts.length) throw firstError;

    const start = Math.min.apply(null, starts);
    const open = cleaned[start];
    const close = open === '[' ? ']' : '}';
    const end = cleaned.lastIndexOf(close);
    if (end <= start) throw firstError;
    return JSON.parse(cleaned.slice(start, end + 1));
  }
}

let summary;
try {
  summary = parseJsonFromOutput($json.output);
} catch (e) {
  const raw = cleanAgentOutput($json.output);
  summary = {
    error: 'parse failed',
    details: e.message,
    raw: raw.slice(0, 2000),
    problem: 'N/A',
    method: 'N/A',
    dataset: 'N/A',
    architecture: 'N/A',
    results: 'N/A',
    limitations: 'N/A',
    novelty: 'N/A'
  };
}

summary = summary && typeof summary === 'object' && !Array.isArray(summary) ? summary : { raw: summary };

return {
  json: Object.assign({}, summary, {
    _meta: {
      title: summary.title || 'Untitled',
      authors: Array.isArray(summary.authors) ? summary.authors : (summary.authors ? String(summary.authors).split(/,\s*/) : []),
      year: summary.year || null,
      citations: summary.citations == null ? null : summary.citations,
      url: summary.url || '',
      source: summary.source || '',
      doi: summary.doi || null,
      relevance_reason: summary.relevance_reason || '',
      paper_type: summary.paper_type || ''
    }
  })
};

const items = $input.all();
const summaries = items.map(function (i) { return i.json; });
const form = $('Research Form').first().json;
const topic = form['Research topic'] || form.topic || '';
return [{ json: { topic: topic, summaries: summaries, paper_count: summaries.length } }];

